function normalizeJobCommand(s){return s.trim().replace(/;\s*$/,'').split(/('[^']*'|"[^"]*")/g).map((v,i)=>i%2?v:v.replace(/\s+/g,' ')).join('');}
function normalizeDMSQL(s){return normalizeJobCommand(s).split(/('[^']*'|"[^"]*")/g).map((v,i)=>i%2?v:v.toUpperCase().replace(/\s*([,=()])\s*/g,'$1')).join('');}
function splitPipeline(raw){let quote='',parts=[],part='';for(const ch of raw){if(ch===quote)quote='';else if(!quote&&(ch==='"'||ch==="'"))quote=ch;if(ch==='|'&&!quote){if(!part.trim())throw Error('管道左侧缺少命令。');parts.push(part.trim());part='';}else part+=ch;}if(quote)throw Error('引号没有闭合。');if(!part.trim())throw Error('管道右侧缺少命令。');return [...parts,part.trim()];}
class JobEngine extends BaseOpsEngine {
 constructor(){super();Object.assign(this.fs,jobFiles);}
 execute(raw){try{if(!raw.trim()||raw.length>2000)throw Error('请输入不超过 2000 字的命令。');let out;const key=normalizeJobCommand(raw);if(/^(SELECT|EXPLAIN|BACKUP)\b/i.test(key)){const found=Object.keys(dmQueries).find(k=>normalizeDMSQL(k)===normalizeDMSQL(key));if(!found)throw Error('本教学 DM8 仅模拟课程列出的语句；请核对表名、列名和当前任务。');out=dmQueries[found];}else {for(const part of splitPipeline(raw))out=this.jobRun(part,out);}this.history.push(raw);return {ok:true,out:out||'(成功，无输出)'};}catch(e){return {ok:false,out:e.message};}}
 jobRun(c,input){const key=normalizeJobCommand(c);if(key in jobProbes)return jobProbes[key];const t=this.tokenize(c),cmd=t.shift();const lines=()=>String(input??'')===''?[]:String(input).trimEnd().split('\n');
  if(cmd==='grep'){let fixed=false,n=false,insensitive=false,context=0,args=[];for(let i=0;i<t.length;i++){if(t[i]==='-F')fixed=true;else if(t[i]==='-n')n=true;else if(t[i]==='-i')insensitive=true;else if(t[i]==='-C')context=Number(t[++i]);else if(t[i]==='--')args.push(...t.slice(i+1));else if(t[i].startsWith('-'))throw Error('本练习支持 grep -F、-n、-i、-C。');else args.push(t[i]);}const pattern=args[0];if(pattern===undefined)throw Error('grep 缺少模式。');let source=input;if(args[1]){source=this.fs[this.path(args[1])];if(source===undefined)throw Error('文件不存在。');}if(source===undefined)throw Error('grep 需要文件或管道输入。');let regex;if(!fixed)regex=new RegExp(pattern,insensitive?'i':'');const ls=String(source)===''?[]:String(source).trimEnd().split('\n'),selected=new Set();ls.forEach((s,i)=>{if(fixed?(insensitive?s.toLowerCase().includes(pattern.toLowerCase()):s.includes(pattern)):regex.test(s))for(let j=Math.max(0,i-context);j<=Math.min(ls.length-1,i+context);j++)selected.add(j);});return [...selected].sort((a,b)=>a-b).map(i=>(n?i+1+':':'')+ls[i]).join('\n');}
  if(cmd==='awk'){if(input===undefined)throw Error('本练习 awk 从管道读取文本。');const match=t.join(' ').match(/^\{print \$(\d+)\}$/);if(!match)throw Error("本练习支持 awk '{print $4}' 一类按空白提取列的表达式。");return lines().map(s=>s.trim().split(/\s+/)[Number(match[1])-1]||'').join('\n');}
  if(cmd==='sort'){if(input===undefined)throw Error('sort 需要管道输入。');if(t.length&&!['-nr','-n','-r'].includes(t[0]))throw Error('支持 sort、-n、-r、-nr。');const ls=lines().sort(t[0]?.includes('n')?(a,b)=>parseFloat(a)-parseFloat(b):undefined);return (t[0]?.includes('r')?ls.reverse():ls).join('\n');}
  if(cmd==='uniq'){if(input===undefined)throw Error('uniq 需要管道输入。');if(t.length&&t[0]!=='-c')throw Error('本练习支持 uniq 与 uniq -c。');const groups=[];for(const line of lines()){const last=groups.at(-1);if(last?.s===line)last.n++;else groups.push({s:line,n:1});}return groups.map(g=>t[0]==='-c'?String(g.n).padStart(7)+' '+g.s:g.s).join('\n');}
  if(cmd==='wc'&&t[0]==='-l'&&input!==undefined)return String(input.trim()?lines().length:0);
  if(cmd==='tee'&&t.length===1&&input!==undefined){this.fs[this.path(t[0])]=input+'\n';return input;}
  if(cmd==='find'&&key==='find /opt/order -name "*.log"')return '/opt/order/logs/app.log';
  return super.run(c,input);
 }
}
function addWork(id,section,title,body,rows,question,correct,wrong,related,source='dm'){
 const i=hubCurriculum.opswork.length;hubCurriculum.opswork.push({id,section,title,summary:body.split('。')[0]+'。',body:[body,related],related,diagram:section==='页面到服务'?'trace':section==='高效命令'?'pipeline':section==='DM8 与业务数据'?'database':'deploy',source:source==='dm'?['达梦官方文档','https://eco.dameng.com/document/dm/zh-cn/faq/faq-db-check']:source==='nginx'?['Nginx 官方文档','https://nginx.org/en/docs/']:['GNU Bash 手册','https://www.gnu.org/software/bash/manual/'],examples:rows.map(r=>({text:r[0],meaning:r[1]})),tasks:rows.map(r=>({type:'command',prompt:r[2]||r[1],command:r[0],expected:r[3]||'',explanation:r[1]})),quiz:choiceTask(question,correct,wrong,related,i)});
}
